function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}function move(a,dx,dz){stepMotion(a,dx,dz,(x,z)=>a===p&&interior?roomBlocked(x,z):blocked(x,z)||(a.exam&&examRun&&Math.hypot(x-examRun.arena.x,z-examRun.arena.z)>examRun.arena.r-.45)||(a.regional&&x<51)||(!a.regional&&((Number.isInteger(a.id)&&a.id>=0&&a.id<DATA.enemies.length)||a.patrol||a.temporary||a.eventEnemy)&&x>49));}
