function activeEnemies(){if(examRun||interior||mistScene||boss?.scripted)return [];const east=inEast(p),original=east?regionalEnemies:enemies;return boss?original:[...original,...patrols.filter(e=>!!e.regional===east),...reinforcements.filter(e=>!!e.regional===east),...(worldEvent?.actors||[]).filter(e=>!!e.regional===east)];}
function resetLiving(){liveNPCs=NPCS.map(n=>({...n,homeX:n.x,homeZ:n.z,walk:0,dirX:0,dirZ:1}));interior=null;roomNPC=null;weatherOverride=null;weatherState=newWeather(t);worldEvent=null;nextEventAt=t;eventExplore=0;eventBannerUntil=0;if($('eventBanner'))$('eventBanner').hidden=true;nextThunderAt=t+5;}
