function startWorldEvent(type){const spec=WORLD_EVENTS[type];if(!spec||worldEvent||interior||boss||examRun||p.x<14)return false;const east=inEast(p);let pos=null;for(const [dx,dz] of [[6,3],[-6,3],[4,-5],[-4,-5],[0,7],[0,-7],[7,0],[-7,0]]){const candidate=spawnPosition({x:p.x+dx,z:p.z+dz,regional:east});if(candidate&&dist(p,candidate)>=3.5&&dist(p,candidate)<=11&&clearRasPath(p,candidate)){pos=candidate;break;}}if(!pos)return false;const actors=[];for(const [i,role] of (spec.roles||[]).entries()){const at=spawnPosition({x:pos.x+i*1.6,z:pos.z+(i%2?2:-1),regional:east});if(!at||!clearRasPath(pos,at))return false;actors.push({...prepareEnemy({id:400+i,...at,role,hp:65,maxHP:65,hit:0,attack:1}),eventEnemy:true,regional:east});}worldEvent={type,...pos,actors,expires:t+spec.duration};eventExplore=0;showEventBanner('EVENT: '+spec.banner,spec.objective+' · '+spec.duration+' s');audio.play('event');msg('Event! '+spec.name,5);return true;}
