function tickMistAllies(dt){if(!boss?.scripted||mistScene)return;for(const ally of mistAllies){if(ally.hp<=0)continue;ally.flash=Math.max(0,ally.flash-dt);ally.attack=Math.max(0,ally.attack-dt);if(ally.anim){ally.anim.left-=dt;if(ally.anim.left<=0)ally.anim=null;}const mirror=ally.kind==='sasuke'&&boss.id==='haku'?mistMirrors.filter(m=>m.hp>0&&dist(ally,m)<5&&clearRasPath(ally,m)).sort((a,b)=>dist(ally,a)-dist(ally,b))[0]:null;const target=mirror||boss,v=directionToward(target.x-ally.x,target.z-ally.z);ally.dirX=v.x;ally.dirZ=v.z;ally.motion=false;const d=dist(ally,target);if(d>ally.spec.reach*.7){move(ally,v.x*dt*ally.spec.speed,v.z*dt*ally.spec.speed);ally.motion=true;ally.walk+=dt*8;}if(ally.attack<=0&&d<=ally.spec.reach&&clearRasPath(ally,target)){ally.attack=ally.spec.cooldown;ally.anim={k:'j',left:.4,total:.4};effects.push({x:target.x,z:target.z,type:ally.spec.effect,life:.45,max:.45,r:1.5,col:ally.kind==='sasuke'?C.orange:C.blue});hurt(target,ally.spec.damage,ally,{...COMBAT.skills.j,freeze:0,shake:.01});if(mistScene)return;}}}
