 const critical=allowCrit&&Math.random()<COMBAT.criticalChance+bonus.crit+characterFor(p.character).crit+(p.focus>0?.22:0);
 const coordinated=(source===p||source.owner==='player')&&p.character==='naruto'&&e.mark>0&&(skill===COMBAT.skills[' ']||skill===COMBAT.skills.g||skill.narutoImpact);
