 const target=combatTargets().filter(e=>e.hp>0&&dist(p,e)<=spec.minDistance+spec.contact&&(dist(p,e)<1.5||(e.x-p.x)*v.x+(e.z-p.z)*v.z>dist(p,e)*.65)).sort((a,b)=>dist(p,a)-dist(p,b))[0];
