const keyLabel=k=>({ ' ':'SPACE',shift:'SHIFT',control:'CTRL',alt:'ALT',enter:'ENTER',tab:'TAB',backspace:'BACKSPACE'}[k]||k.toUpperCase());
const actionKey=a=>keyLabel(bindings[a]||a);
